// Lee las series extraídas. CoinGecko devuelve [[timestamp, precio], …] y la extracción las aplana a "ts,precio,ts,precio…".
const f = (t) => new Date(t).toISOString().slice(0, 10);
const serie = (txt) => { const n = String(txt || '').split(',').map(Number).filter(Number.isFinite); const out = []; for (let i = 0; i + 1 < n.length; i += 2) out.push({ t: n[i], p: n[i + 1] }); return out.filter((r, i, a) => i === a.length - 1 || f(r.t) !== f(a[i + 1].t)); }; // un punto por día (el último es el precio actual)
const sma = (a, n) => a.length >= n ? a.slice(-n).reduce((s, v) => s + v, 0) / n : null;
const rsi = (a, n = 14) => { if (a.length <= n) return null; let g = 0, l = 0; for (let i = a.length - n; i < a.length; i++) { const d = a[i] - a[i - 1]; if (d >= 0) g += d; else l -= d; } return l === 0 ? 100 : 100 - 100 / (1 + (g / n) / (l / n)); };
const analiza = (nombre, txt) => {
  const rows = serie(txt); if (rows.length < 52) return { nombre, error: 'serie insuficiente (' + rows.length + ' puntos)' };
  const p = rows.map(r => r.p), ult = p.at(-1);
  const s20 = sma(p, 20), s50 = sma(p, 50), r14 = rsi(p);
  const var7 = 100 * (ult / p.at(-8) - 1), var30 = 100 * (ult / p.at(-31) - 1);
  const tendencia = ult > s20 && s20 > s50 ? 'ALCISTA' : ult < s20 && s20 < s50 ? 'BAJISTA' : 'MIXTA';
  const senal = tendencia === 'ALCISTA' && r14 < 70 ? 'COMPRA · tendencia alcista y RSI sin sobrecompra' : tendencia === 'BAJISTA' && r14 > 30 ? 'VENTA · tendencia bajista y RSI sin sobreventa' : 'ESPERAR · sin tendencia clara o RSI en zona extrema';
  return { nombre, ult, s20, s50, r14, var7, var30, max90: Math.max(...p), min90: Math.min(...p), tendencia, senal, fecha: f(rows.at(-1).t), ultimos30: p.slice(-30).map(v => Math.round(v * 100) / 100), fechas30: rows.slice(-30).map(r => f(r.t).slice(5)) };
};
return JSON.stringify({ generado: new Date().toISOString(), BTC: analiza('Bitcoin', vars.btcSerie), ETH: analiza('Ethereum', vars.ethSerie) });

const a = JSON.parse(vars.criptoEstado || '{}').BTC; if (!a || a.error) return 'Sin datos: ' + (a?.error || 'ejecuta el flow');
const n = (v, d = 0) => Number(v).toLocaleString('es-ES', { minimumFractionDigits: d, maximumFractionDigits: d });
return `${a.nombre} · ${n(a.ult)} USD (${a.fecha})
${a.senal}
Tendencia ${a.tendencia} · SMA20 ${n(a.s20)} · SMA50 ${n(a.s50)} · RSI14 ${n(a.r14, 1)}
7 días ${n(a.var7, 2)} % · 30 días ${n(a.var30, 2)} %
Rango 90 días: ${n(a.min90)} – ${n(a.max90)} USD`;

const a = JSON.parse(vars.criptoEstado || '{}').ETH; if (!a || a.error) return 'Sin datos: ' + (a?.error || 'ejecuta el flow');
const n = (v, d = 0) => Number(v).toLocaleString('es-ES', { minimumFractionDigits: d, maximumFractionDigits: d });
return `${a.nombre} · ${n(a.ult)} USD (${a.fecha})
${a.senal}
Tendencia ${a.tendencia} · SMA20 ${n(a.s20)} · SMA50 ${n(a.s50)} · RSI14 ${n(a.r14, 1)}
7 días ${n(a.var7, 2)} % · 30 días ${n(a.var30, 2)} %
Rango 90 días: ${n(a.min90)} – ${n(a.max90)} USD`;

// Devuelve un diagrama Mermaid (xychart) que la nota de al lado pinta en vivo.
const a = JSON.parse(vars.criptoEstado || '{}').BTC;
if (!a || a.error) return 'xychart-beta
  title "Sin datos: ejecuta el flow"
  x-axis ["-"]
  y-axis "USD" 0 --> 1
  line [0]';
const lo = Math.min(...a.ultimos30), hi = Math.max(...a.ultimos30), m = (hi - lo) * 0.08 || 1;
return `xychart-beta
  title "Bitcoin · últimos 30 días (USD) · barras = cierre · línea = SMA20"
  x-axis [${a.fechas30.map(f => '"' + f + '"').join(', ')}]
  y-axis "USD" ${Math.floor(lo - m)} --> ${Math.ceil(hi + m)}
  bar [${a.ultimos30.map(v => Math.round(v)).join(', ')}]
  line [${a.ultimos30.map(() => Math.round(a.s20)).join(', ')}]`;
